WITH metric AS (SELECT mktcode,tgtcode,(MAX_BY(volume,bizdate)-MIN_BY(volume,bizdate))*100/NULLIF(ABS(MIN_BY(volume,bizdate)),0) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) GROUP BY mktcode,tgtcode), qualified AS (SELECT mktcode,tgtcode FROM metric WHERE value>0) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
